dashboard.definition:
{
  "title": "AI provider setup",
  "description": "Set provider, model, and key, then click SAVE. Search does not open.",
  "defaults": {},
  "inputs": {
    "input_cfg_provider": {
      "type": "input.dropdown",
      "title": "AI provider",
      "options": {
        "token": "tok_cfg_provider",
        "defaultValue": "none",
        "items": [
          {
            "label": "None \u2014 local briefing only",
            "value": "none"
          },
          {
            "label": "OpenAI",
            "value": "openai"
          },
          {
            "label": "Cisco AI Defense",
            "value": "cisco"
          },
          {
            "label": "Azure OpenAI",
            "value": "azure"
          },
          {
            "label": "Anthropic",
            "value": "anthropic"
          },
          {
            "label": "Custom OpenAI-compatible",
            "value": "custom"
          }
        ]
      }
    },
    "input_cfg_model": {
      "type": "input.text",
      "title": "Model",
      "options": {
        "token": "tok_cfg_model",
        "defaultValue": ""
      }
    },
    "input_cfg_key": {
      "type": "input.text",
      "title": "API key",
      "options": {
        "token": "tok_cfg_key",
        "defaultValue": ""
      }
    },
    "input_cfg_save": {
      "type": "input.text",
      "title": "Save latch (set by SAVE)",
      "options": {
        "token": "tok_cfg_save",
        "defaultValue": "review"
      }
    }
  },
  "dataSources": {
    "ds_ai_current": {
      "type": "ds.search",
      "name": "Saved AI config",
      "options": {
        "query": "| inputlookup dq_agent_ai_config\n| where stanza=\"default\"\n| head 1\n| eval used_ui=if(updated_at=\"0\" OR isnull(updated_at), 0, 1)\n| eval mode=if(used_ui=0, \"`exec_health_ai_mode`\", coalesce(mode, \"off\"))\n| eval provider=if(used_ui=0, \"`exec_health_ai_provider`\", coalesce(provider, \"none\"))\n| eval model=if(used_ui=0, \"`exec_health_ai_model`\", coalesce(model, \"none\"))\n| eval endpoint=if(used_ui=0, \"`exec_health_ai_endpoint`\", coalesce(endpoint, \"none\"))\n| eval inbox_index=coalesce(inbox_index, \"_internal\")\n| eval inbox_sourcetype=coalesce(inbox_sourcetype, \"derek_health_ai_unconfigured\")\n| lookup dq_agent_ai_providers provider OUTPUT provider_label, default_endpoint, notes\n| eval endpoint=if(endpoint=\"none\" OR endpoint=\"\", coalesce(default_endpoint, \"none\"), endpoint)\n| eval key_state=if(isnotnull(api_key) AND api_key!=\"\" AND api_key!=\"none\", \"SET\", \"MISSING\")\n| eval ai_status=case(mode=\"provider\" AND provider!=\"none\" AND provider!=\"\" AND key_state=\"SET\", \"PROVIDER\", mode=\"provider\", \"MISCONFIG\", 1=1, \"LOCAL\")\n| eval status_color=case(ai_status=\"PROVIDER\", \"YELLOW\", ai_status=\"MISCONFIG\", \"RED\", 1=1, \"GREEN\")\n| eval _color_rank=case(ai_status=\"MISCONFIG\", 1, ai_status=\"PROVIDER\", 2, 1=1, 3)\n| table ai_status, status_color, mode, provider, provider_label, model, key_state, endpoint, inbox_index, inbox_sourcetype, notes, _color_rank\n\n| eval _gate=\"$tok_cfg_save$\"",
        "refresh": "10s",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_ai_providers": {
      "type": "ds.search",
      "name": "Provider catalog",
      "options": {
        "query": "| inputlookup dq_agent_ai_providers | eval _color_rank=3 | table provider, provider_label, default_endpoint, notes, _color_rank",
        "refresh": "5m",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_ai_save": {
      "type": "ds.search",
      "name": "Save control",
      "options": {
        "query": "| makeresults\n| eval button_label=\"SAVE\"\n| eval click_action=\"save\"\n| eval _color_rank=3\n| table button_label, click_action, _color_rank",
        "refresh": "30s",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_ai_write": {
      "type": "ds.search",
      "name": "Write AI config",
      "options": {
        "query": "| makeresults\n| eval save=\"$tok_cfg_save$\"\n| eval stanza=\"default\"\n| lookup dq_agent_ai_config stanza OUTPUT inbox_index AS prev_inbox, inbox_sourcetype AS prev_st, endpoint AS prev_endpoint, api_key AS prev_key\n| eval provider=replace(lower(\"$tok_cfg_provider$\"), \"[^a-z]\", \"\")\n| eval provider=if(provider=\"openai\" OR provider=\"cisco\" OR provider=\"azure\" OR provider=\"anthropic\" OR provider=\"custom\", provider, \"none\")\n| eval model=replace(\"$tok_cfg_model$\", \"[^A-Za-z0-9._-]\", \"\")\n| eval model=if(model=\"\" OR isnull(model), \"none\", model)\n| eval api_key=replace(\"$tok_cfg_key$\", \"[^A-Za-z0-9._/=+-]\", \"\")\n| eval api_key=if(api_key=\"\" OR isnull(api_key) OR api_key=\"none\", coalesce(prev_key, \"none\"), api_key)\n| eval api_key=if(provider=\"none\", \"none\", api_key)\n| where save=\"save\" AND (provider=\"none\" OR (provider!=\"none\" AND model!=\"none\" AND api_key!=\"none\" AND api_key!=\"\"))\n| eval mode=if(provider=\"none\", \"off\", \"provider\")\n| lookup dq_agent_ai_providers provider OUTPUT default_endpoint\n| eval endpoint=coalesce(default_endpoint, prev_endpoint, \"none\")\n| eval inbox_index=coalesce(prev_inbox, \"main\")\n| eval inbox_sourcetype=coalesce(prev_st, \"derek_health_ai\")\n| eval updated_by=\"human_dashboard\", updated_at=strftime(now(), \"%Y-%m-%d %H:%M:%S\"), note=\"ui_config\"\n| table stanza, mode, provider, model, endpoint, api_key, inbox_index, inbox_sourcetype, updated_by, updated_at, note\n| appendpipe [\n    | inputlookup append=true dq_agent_ai_config\n    | stats latest(mode) as mode, latest(provider) as provider, latest(model) as model, latest(endpoint) as endpoint, latest(api_key) as api_key, latest(inbox_index) as inbox_index, latest(inbox_sourcetype) as inbox_sourcetype, latest(updated_by) as updated_by, latest(updated_at) as updated_at, latest(note) as note by stanza\n    | outputlookup dq_agent_ai_config\n]\n| where stanza=\"default\"\n| eval key_state=if(api_key!=\"none\" AND api_key!=\"\", \"SET\", \"MISSING\")\n| eval _color_rank=3\n| table updated_at, provider, model, key_state, mode, _color_rank",
        "refresh": "5m",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    }
  },
  "visualizations": {
    "viz_header": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# AI provider setup\nFill in **AI provider**, **model**, and **API key**, then click **SAVE** on the same row. That writes Splunk config on this search head (`dq_agent_ai_config`). Search does not open. The key is never shown after save. Leave key blank to keep the value already stored.",
        "fontSize": "default",
        "backgroundColor": "transparent"
      }
    },
    "viz_status": {
      "type": "splunk.singlevalue",
      "title": "Current mode",
      "dataSources": {
        "primary": "ds_ai_current"
      },
      "showLastUpdated": true,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"ai_status\") | lastPoint()",
        "majorColor": "> primary | seriesByName(\"ai_status\") | lastPoint() | matchValue(statusColors)",
        "backgroundColor": "transparent",
        "majorFontSize": 36
      },
      "context": {
        "statusColors": [
          {
            "match": "GREEN",
            "value": "#53A051"
          },
          {
            "match": "YELLOW",
            "value": "#F8BE34"
          },
          {
            "match": "RED",
            "value": "#DC4E41"
          },
          {
            "match": "N/A",
            "value": "#F8BE34"
          },
          {
            "match": "LOCAL",
            "value": "#53A051"
          },
          {
            "match": "PROVIDER",
            "value": "#F8BE34"
          },
          {
            "match": "MISCONFIG",
            "value": "#DC4E41"
          },
          {
            "match": "WAIT",
            "value": "#6B6B6B"
          }
        ]
      }
    },
    "viz_steps": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## After you save\n1. Enable **Exec Health - AI provider dispatch**.\n2. Attach a **webhook** in Splunk Web to your gateway if replies should return via HEC.\n3. Open **Derek+ Data Quality Agent**, review a finding, click **ASK**.\nPick **None** and SAVE to turn the provider off.",
        "fontSize": "default",
        "backgroundColor": "transparent"
      }
    },
    "viz_current": {
      "type": "splunk.table",
      "title": "Saved settings (key is stored, not displayed)",
      "dataSources": {
        "primary": "ds_ai_current"
      },
      "showLastUpdated": true,
      "showProgressBar": true,
      "options": {
        "count": 5,
        "showRowNumbers": false,
        "showInternalFields": false,
        "tableFormat": {
          "rowBackgroundColors": "> table | seriesByName(\"_color_rank\") | rangeValue(rowColors)"
        }
      },
      "context": {
        "rowColors": [
          {
            "from": 0,
            "to": 1.5,
            "value": "#5C1A1A"
          },
          {
            "from": 1.5,
            "to": 2.5,
            "value": "#5C4A12"
          },
          {
            "from": 2.5,
            "to": 4,
            "value": "#14301A"
          }
        ]
      }
    },
    "viz_providers": {
      "type": "splunk.table",
      "title": "Supported providers",
      "dataSources": {
        "primary": "ds_ai_providers"
      },
      "showLastUpdated": true,
      "showProgressBar": true,
      "options": {
        "count": 10,
        "showRowNumbers": false,
        "showInternalFields": false,
        "tableFormat": {
          "rowBackgroundColors": "> table | seriesByName(\"_color_rank\") | rangeValue(rowColors)"
        }
      },
      "context": {
        "rowColors": [
          {
            "from": 0,
            "to": 1.5,
            "value": "#5C1A1A"
          },
          {
            "from": 1.5,
            "to": 2.5,
            "value": "#5C4A12"
          },
          {
            "from": 2.5,
            "to": 4,
            "value": "#14301A"
          }
        ]
      }
    },
    "viz_save": {
      "type": "splunk.table",
      "title": "SAVE",
      "dataSources": {
        "primary": "ds_ai_save"
      },
      "showLastUpdated": false,
      "showProgressBar": false,
      "options": {
        "count": 1,
        "showRowNumbers": false,
        "showInternalFields": false,
        "tableFormat": {
          "rowBackgroundColors": "> table | seriesByName(\"_color_rank\") | rangeValue(rowColors)"
        },
        "headerVisibility": "none",
        "columnFormat": {
          "button_label": {
            "width": 420,
            "align": "center"
          },
          "click_action": {
            "width": 1
          }
        }
      },
      "context": {
        "rowColors": [
          {
            "from": 0,
            "to": 1.5,
            "value": "#5C1A1A"
          },
          {
            "from": 1.5,
            "to": 2.5,
            "value": "#5C4A12"
          },
          {
            "from": 2.5,
            "to": 4,
            "value": "#14301A"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.setToken",
          "options": {
            "tokens": [
              {
                "token": "tok_cfg_save",
                "key": "row.click_action.value"
              }
            ]
          }
        }
      ]
    },
    "viz_write": {
      "type": "splunk.singlevalue",
      "title": "",
      "dataSources": {
        "primary": "ds_ai_write"
      },
      "hideWhenNoData": true,
      "showLastUpdated": false,
      "showProgressBar": false,
      "options": {
        "majorValue": "> primary | seriesByName(\"key_state\") | lastPoint()",
        "backgroundColor": "transparent",
        "majorFontSize": 14
      }
    },
    "viz_footer": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "SAVE updates `lookups/dq_agent_ai_config.csv` on this search head only. The install package ships `api_key=none`. HEC token secrets and webhook URLs still do not belong in this app.",
        "fontSize": "default",
        "backgroundColor": "transparent"
      }
    }
  },
  "layout": {
    "type": "grid",
    "structure": [
      {
        "item": "viz_header",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 1200,
          "h": 90
        }
      },
      {
        "item": "input_cfg_provider",
        "type": "input",
        "position": {
          "x": 0,
          "y": 90,
          "w": 250,
          "h": 95
        }
      },
      {
        "item": "input_cfg_model",
        "type": "input",
        "position": {
          "x": 250,
          "y": 90,
          "w": 250,
          "h": 95
        }
      },
      {
        "item": "input_cfg_key",
        "type": "input",
        "position": {
          "x": 500,
          "y": 90,
          "w": 400,
          "h": 95
        }
      },
      {
        "item": "viz_save",
        "type": "block",
        "position": {
          "x": 900,
          "y": 90,
          "w": 300,
          "h": 95
        }
      },
      {
        "item": "viz_status",
        "type": "block",
        "position": {
          "x": 0,
          "y": 185,
          "w": 300,
          "h": 150
        }
      },
      {
        "item": "viz_steps",
        "type": "block",
        "position": {
          "x": 300,
          "y": 185,
          "w": 900,
          "h": 150
        }
      },
      {
        "item": "viz_current",
        "type": "block",
        "position": {
          "x": 0,
          "y": 335,
          "w": 1200,
          "h": 180
        }
      },
      {
        "item": "viz_providers",
        "type": "block",
        "position": {
          "x": 0,
          "y": 515,
          "w": 1200,
          "h": 220
        }
      },
      {
        "item": "viz_footer",
        "type": "block",
        "position": {
          "x": 0,
          "y": 735,
          "w": 1200,
          "h": 80
        }
      },
      {
        "item": "viz_write",
        "type": "block",
        "position": {
          "x": 0,
          "y": 815,
          "w": 1200,
          "h": 40
        }
      }
    ]
  }
}
